# ---- ids toekennen: gemengd, geen twee dezelfde sjablonen achter elkaar ----
def _assign():
    rnd = random.Random(2026)
    order = ITEMS[:]
    for _ in range(200):
        rnd.shuffle(order)
        if all(order[i]['tpl'] != order[i + 1]['tpl'] for i in range(len(order) - 1)): break
    for i, it in enumerate(order):
        it['id'] = 's%03d' % (i + 1)
    return sorted(order, key=lambda x: x['id'])
JOBS = _assign()
